import base64,hashlib,os,platform,stat,sys,zlib
from pathlib import Path
assert os.getuid()==os.geteuid()==1204 and os.getgid()==os.getegid()==1205 and platform.node()=='server1', 'Use ordinary jwk on A'
raw=zlib.decompress(base64.b64decode('',validate=True))
assert len(raw)==10485 and hashlib.sha256(raw).hexdigest()=='5e163b503c7c5924f3961100dc8ffda7a3f91754ba9854cf6d4f76353e383a91'
p=Path('/home/jwk/agent/A_resume_private_delete_daemon_v2.py')
assert p.parent.resolve(strict=True)==p.parent and not p.is_symlink()
if p.exists():
    fd=os.open(p,os.O_RDONLY|os.O_NOFOLLOW|os.O_CLOEXEC)
    with os.fdopen(fd,'rb') as stream:
        meta=os.fstat(stream.fileno())
        assert stat.S_ISREG(meta.st_mode) and meta.st_uid==1204 and meta.st_nlink==1 and meta.st_mode&0o022==0
        assert stream.read(len(raw)+1)==raw
else:
    fd=os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
    with os.fdopen(fd,'wb') as stream:
        stream.write(raw);stream.flush();os.fsync(stream.fileno())
print('PRIVATE_DELETE_DAEMON_RESUME_ENTRY_VERIFIED',flush=True)
sys.argv=[str(p),'--run']
exec(compile(raw,str(p),'exec'),{'__name__':'__main__','__file__':str(p)})
